void CQuat::MakeXRot(float angle)
{
	/* 0x221820: rotation by angle about x */
	f32 half = 0.5f * angle;
	vec.x = sinf(half);
	w = cosf(half);
	vec.y = 0.0f;
	vec.z = 0.0f;
}

