/* @socom-skeleton stub MakeYXRot__5CQuatFff */
void CQuat::MakeYXRot(float yaw, float pitch)
{
	/* 0x2216b0: rotation by yaw about y, then pitch about x (y * x) */
	f32 hy = 0.5f * yaw;
	f32 sy = sinf(hy);
	f32 cy = cosf(hy);
	f32 hx = 0.5f * pitch;
	f32 sx = sinf(hx);
	f32 cx = cosf(hx);
	w = cy * cx;
	vec.x = cy * sx;
	vec.y = sy * cx;
	vec.z = -sy * sx;
}

