/* @socom-skeleton stub Pow__5CQuatFfP5CQuat */
void CQuat::Pow(float t, CQuat *out)
{
	/* 0x220610: the rotation's angle scaled by t (the short way round) */
	f32 len2 = vec.z * vec.z + vec.x * vec.x + vec.y * vec.y;

	if (len2 == 0.0f)
	{
		*out = *this;
		return;
	}

	f32 len = sqrtf(len2);
	f32 angle;

	if (w >= 0.0f)
		angle = t * atan2f(len, w);
	else
		angle = t * -atan2f(len, -w);

	f32 s = sinf(angle);
	out->w = cosf(angle);
	CPnt3D v;
	vec.Scale(s / len, &v);
	out->vec.x = v.x;
	out->vec.y = v.y;
	out->vec.z = v.z;
}

